    "id": "usp-sp-2026-002",
    "number": 2,
    "stem": "Mulher, 28 anos de idade, previamente hígida, procura atendimento de urgência. Queixa-se de diarreia aquosa há 4 dias com febre baixa. Teve 6 episódios por dia, com cólicas intensas, náuseas e hiporexia. O seu filho de 4 anos de idade está com os mesmos sintomas. Sinais vitais com PA de 110×68 mmHg, FC de 94 bpm, FR de 18 irpm, SpO2 de 99%, temperatura de 37,1 °C. Ao exame clínico, apresenta regular estado geral, mucosas secas, peristalse aumentada, desconforto abdominal difuso. • Exames laboratoriais: Hb: 13,7 g/dL Leucócitos: 15.890/mm3 Plaquetas: 384 mil/mm3 Ur: 47 mg/dL Cr: 1,18 mg/dL Na+: 128 mEq/L K+: 3,7 mEq/L HCO3-: 29 mEq/L Assinale a alternativa que apresenta um mecanismo fisiopatológico que faz parte do desenvolvimento da hiponatremia desta paciente.",
