    "id": "usp-sp-2026-098",
    "number": 98,
    "stem": "Mulher, 58 anos de idade, menopausada, refere desconforto pélvico e sensação de “peso” na região vaginal, que se acentua ao final do dia e após longos períodos em pé. Também refere dificuldade para evacuar, com necessidade frequente de realizar manobras digitais para completar a evacuação. Apresenta atividade sexual regular com uso de lubrificantes à base de óleos naturais. Durante o exame ginecológico com manobra de Valsalva, observa-se que a parede vaginal posterior ultrapassa o hímen em 2 cm e o colo uterino exterioriza-se 1 cm além do hímen. Assinale a alternativa que apresenta a melhor conduta terapêutica a ser considerada neste caso.",
