    "number": 113,
    "stem": "Mulher, 52 anos de idade, em consulta de rotina refere ciclos menstruais com intervalos de 45 dias há 5 meses. Também notou perda progressiva de interesse sexual e prejuízo no relacionamento conjugal. Nesses meses, relata dificuldade com a memória. Tem estado cansada e já não está mais indo aos almoços com as amigas. Está se alimentando bem, até com mais apetite do que o costume e ganhou peso no último mês. Nega antecedente de trombose venosa ou doença cardiovascular. Exame pélvico mostra mucosa vaginal sem atrofia significativa; restante do exame físico é normal. Ela se considera uma mulher forte, nega tristeza e expressa vontade de tomar um medicamento que pudesse melhorar o sono e reduzir o apetite. Considerando o quadro descrito, assinale a alternativa que apresenta o tratamento medicamentoso mais indicado.",
