    "stem": "Mulher, 25 anos de idade, nuligesta, procura aconselhamento sobre métodos de planejamento familiar. Ela deseja evitar métodos hormonais por motivos pessoais e busca uma opção natural. Qual a orientação que deve ser fornecida sobre o reconhecimento do período fértil segundo o método de Billings?",
