    "number": 120,
    "stem": "Tercigesta secundípara, com estenose mitral reumática, comparece na maternidade com gestação de 37 semanas e 6 dias em trabalho de parto espontâneo. Refere perda de líquido amniótico típica há 8 horas. Pesquisa de Estreptococo grupo B não realizada. Considerando parto vaginal não complicado, qual é a profilaxia antibiótica indicada?",
