    "id": "usp-sp-2025-049",
    "number": 49,
    "stem": "Homem, 64 anos de idade, tentou suicídio com ferimento por arma branca no tórax. No atendimento inicial, o paciente encontrava-se com a faca introduzida na parede anterior do tórax, bastante agitado e com PA de 140x90 mmHg e FC de 110 bpm. Devido à agitação, optou-se pela intubação para transporte. Na admissão no Centro de Trauma encontrava-se:\n\nA: Intubado. Saturação de oxigênio de 97%.\nB: MV presentes e sem alterações. Inspeção torácica demonstrada na figura a seguir.\nC: PA de 130x80 mmHg; FC de 110 bpm; e-FAST negativo.\nD: Sedado com pupilas mióticas. Escala de coma de Glasgow 3.\nE: Sem outros achados além da lesão torácica.\n\nAssinale a alternativa que indica o próximo passo a ser realizado na condução do caso.",
