    "number": 50,
    "stem": "Homem, 63 anos de idade, foi admitido no Serviço de Emergência com dor na região inguinal à direita e com abaulamento local há 8 horas, acompanhados de distensão abdominal e dois episódios de vômitos. Tem antecedente de doença pulmonar obstrutiva crônica em uso de oxigênio domiciliar. Ao exame físico, encontrava-se em regular estado geral e desidratado, ausculta pulmonar e cardíaca sem alterações; abdome distendido, sem dor à palpação profunda e sem sinais de irritação peritoneal; região inguinal direita com abaulamento local endurecido de 4 cm, sem hiperemia e doloroso à palpação.\n\nExames laboratoriais:\nHb: 17,1 g/dL\nHt: 51%\nLeucograma: 8.274/mm3\nCreatinina: 1,9 mg/dL\nUreia: 91 mg/dL\n\nAlém da hidratação e suporte clínico, qual é a melhor conduta neste caso?",
