    "id": "usp-sp-2025-052",
    "number": 52,
    "stem": "Mulher, 42 anos de idade, foi admitida no Serviço de Emergência com icterícia há 1 semana, acompanhada de queda do estado geral e dor abdominal há 2 dias. Relata a urina mais escurecida. Ao exame físico, encontra-se em regular estado geral, temperatura de 38,1 °C, ictérica, FC de 110 bpm, PA de 100x60 mmHg; abdome flácido, doloroso à palpação profunda do hipocôndrio direito, sem massas palpáveis; sem outras alterações.\n\n• Exames laboratoriais:\nHb: 13,9 g/dL\nHt: 40%\nLeucograma: 15.326/mm3\nCreatinina: 1,5 mg/dL\nUreia: 60 mg/dL\nPCR: 180 mg/L\nTGO/AST: 269 U/L\nTGP/ALT: 211 U/L\nFA: 301 U/L\nGGT: 441 U/L\nBilirrubina total: 9,7 mg/dL\nBilirrubina direta: 8,5 mg/dL\nAmilase: 130 U/L\n\nFoi realizada ultrassonografia de abdome com os seguintes achados: vesícula biliar com múltiplos cálculos de até 0,5 cm, paredes finas e sem delaminação, via biliar extra-hepática com 1,1 cm, sem identificação de fatores obstrutivos evidentes ao método. Considerando a principal hipótese diagnóstica, qual é a melhor conduta?",
