    "stem": "Homem, 71 anos de idade, está em programação de tratamento operatório eletivo de hérnia incisional de laparotomia mediana. Faz uso regular de ácido acetilsalicílico, clopidogrel e metformina. Após avaliação pré-operatória, foi liberado pelo clínico para o procedimento. Como deve ser a orientação referente ao uso dos medicamentos?\n\n(A) Ácido acetilsalicílico: Manter | Clopidogrel: Suspender 5 dias antes | Metformina: Suspender 24 horas antes\n(B) Ácido acetilsalicílico: Manter | Clopidogrel: Suspender 48 horas antes | Metformina: Suspender 24 horas antes\n(C) Ácido acetilsalicílico: Suspender 5 dias antes | Clopidogrel: Suspender 48 horas antes | Metformina: Suspender 3 dias antes\n(D) Ácido acetilsalicílico: Suspender 5 dias antes | Clopidogrel: Suspender 5 dias antes | Metformina: Suspender 3 dias antes",
