    "number": 71,
    "stem": "Homem, 27 anos idade, realizou tomografia de tórax com achado incidental de nódulo na tireoide. Na sequência, foi submetido à ultrassonografia Doppler da tireoide que revelou nódulo em terço inferior de lobo esquerdo, predominantemente sólido, hipoecogênico, mais alto do que largo, de margens pouco definidas, com numerosos focos puntiformes hiperecogênicos de permeio, medindo 2,1 x 1,8 x 1,6 cm (TI-RADS ACR 5 - Thyroid Imaging Reporting and Data System American College of Radiology), com fluxo central e periférico equivalentes ao Doppler colorido (Chammas III). Diante desse cenário, qual deve ser a próxima conduta?",
