    "number": 88,
    "stem": "Gestante, 26 anos de idade, está em seguimento pré-natal por diabetes gestacional com dieta nutricional fracionada orientada, diagnosticada por glicemia de jejum de 98 mg/dL no primeiro trimestre. Neste momento, com 26 semanas, retorna em bom estado geral, normotensa, abdome gravídico, AU de 25 cm, BCF+, IMC: 30 kg/m2. Traz perfil glicêmico (em mg/dL):\n\nData | Jejum | 1h após café | 1h após almoço | 1h após jantar\n01/11 | 97 | 142 | 136 | 140\n02/11 | 93 | 120 | 139 | 156\n03/11 | 84 | 134 | 150 | 122\n04/11 | 92 | 144 | 146 | 135\n05/11 | 95 | 134 | 154 | 158\n06/11 | 94 | 100 | 110 | 130\n07/11 | 100 | 142 | 133 | 150\n08/11 | 92 | 138 | 147 | 155\n09/11 | 93 | 148 | 150 | 144\n10/11 | 120 | 141 | 156 | 166\n11/11 | 90 | 138 | 150 | 145\n\nCom base nessas informações, a conduta indicada neste momento é:",
