    "number": 90,
    "stem": "Puérpera, 30 anos de idade, internada em alojamento conjunto, por desproporção céfalo-pélvica, no 2º dia pós-parto cesárea. Teve diabetes gestacional controlado com dieta, além de trombose venosa profunda 1 ano antes da gravidez, tendo feito uso de enoxaparina profilática durante a gestação, suspenso no parto. Logo depois do nascimento, não quis ver a criança, dizendo que estava muito cansada. No primeiro dia pós-parto, teve dificuldade na amamentação, permanecendo a maior parte do tempo no leito. No segundo dia pós-parto, apresentou-se com irritabilidade cada vez maior com o choro do recém-nascido, chegando a chutar o berço com a criança dentro, sob as vistas do marido e da enfermagem. Com o ocorrido, a criança foi afastada da mãe e encaminhada ao berçário. Em conversa reservada com a equipe, o marido revelou que a paciente passou a apresentar isolamento, alteração de sono, choro fácil e irritabilidade durante a gravidez. Qual é a principal hipótese diagnóstica nesse momento?",
