    "id": "usp-sp-2025-098",
    "number": 98,
    "stem": "Paciente, 8 meses de idade, do sexo masculino, é levado ao pronto atendimento por tosse há uma semana, com febre de até 39,5 °C há três dias. O responsável notou que ele apresenta cansaço e dificuldade para respirar. Ao exame físico, está letárgico, pálido e gemente, FC de 172 bpm, FR de 88 ipm, saturando 90% em máscara não reinalante, PA de 85x40 mmHg, temperatura axilar, no momento, de 36,9 °C. Sem alterações em ausculta cardíaca e pulmonar; com presença de tiragens intercostal, subdiafragmática e de fúrcula importantes. Tempo de enchimento capilar de 2 segundos, pulsos cheios. Restante do exame físico sem alterações. Assinale a alternativa que descreve a principal hipótese diagnóstica e a conduta indicada nesse momento.",
