    "stem": "Lactente previamente hígido comparece à primeira consulta médica aos 2 meses de idade. Ao exame clínico, nota-se que o testículo direito não é palpável no escroto nem no canal inguinal. O testículo esquerdo encontra-se tópico. Não há outras alterações no exame físico. Qual é a conduta mais adequada no momento desta consulta?",
