    "stem": "Paciente, 6 anos de idade, com antecedente de síndrome nefrótica corticodependente, iniciou quadro de urina espumosa, edema periorbital e escrotal, lipotimia e derrame pleural após episódio de resfriado comum. Foi indicada a internação para controle da descompensação e indicada infusão de albumina.\n\n• Exames laboratoriais:\nHb: 13,7g/dL\nHt: 45,2%\nLeucócitos: 3.400/mm3, sem desvio\nPlaquetas: 409 mil/mm3\nNa+: 125 mEq/L\nK+: 4,5 mEq/L\nCreatinina: 1,7 mg/dL (anterior de 0,9 mg/dL)\nUreia: 69 mg/dL\nAlbumina: 1,5 g/dL\n\nEvoluiu após 48 horas de internação com queixa de dor abdominal intensa, pior à palpação, com descompressão brusca positiva. Qual processo fisiopatológico está relacionado à complicação apresentada pelo paciente?",
