    "number": 116,
    "stem": "Recém-nascido, 36 horas de vida no alojamento conjunto, apresenta perda ponderal de 4% desde o nascimento e icterícia neonatal zona II de Kramer ao exame físico. Recebe seio materno em livre demanda.\n\nChecadas tipagens sanguíneas:\n- Mãe: A, Rh negativo e Coombs indireto negativo;\n- RN: B, Rh positivo e Coombs direto negativo.\n\nRealizada coleta de bilirrubina total e frações com 37 horas de vida devido à icterícia neonatal:\n- Bilirrubina total: 7 mg/dL\n- Bilirrubina indireta: 6,8 mg/dL\n- Bilirrubina direta: 0,2 mg/dL\n\nEm relação aos resultados de exames e a provável etiologia, assinale a alternativa correta.",
